function normalizeOrganizationAssignments(assignments = {}) {
  return Object.entries(assignments || {}).reduce((normalized, [slotId, userId]) => {
    if (!userId) return normalized;
    const normalizedSlotId = organizationLegacySlotMap[slotId] || slotId;
    if (!normalized[normalizedSlotId]) normalized[normalizedSlotId] = userId;
    return normalized;
  }, {});
}
