// ---------------------------------------------------------------------------
// Stage 4: job mutations. In Supabase mode every mutation goes through the
// approved server RPC and the jobs cache is refreshed ONLY via
// loadJobsFromSupabase() (list_jobs_for_current_user). RPC return objects are
// never merged into the cache. Demo mode keeps the unchanged *Local bodies.
// ---------------------------------------------------------------------------
const jobMutationInFlight = { create: false, assign: false, update: false, verify: false };
function jobMutationErrorText(error) {
  const detail = String(error?.message || error || "");
  if (detail.includes("EVIDENCE_UPLOAD_FAILED")) return "อัปโหลดรูปหลักฐานไม่สำเร็จ กรุณาลองใหม่ / Photo upload failed; please try again";
  if (detail.includes("PIN_INVALID")) return "PIN ไม่ถูกต้อง / Invalid close PIN";
  if (detail.includes("EVIDENCE_REQUIRED")) return "กรุณาแนบรูปหลักฐานตามที่กำหนด / Required photo evidence is missing";
  if (detail.includes("ILLEGAL_TRANSITION")) return "ไม่สามารถเปลี่ยนเป็นสถานะนี้ได้ / This status change is not allowed";
  if (detail.includes("FORBIDDEN")) return "บัญชีนี้ไม่มีสิทธิ์ดำเนินการนี้ / This account is not allowed to perform this action";
  if (detail.includes("AUTH_REQUIRED")) return "เซสชันหมดอายุ กรุณาเข้าสู่ระบบใหม่ / Session expired; please sign in again";
  if (detail.includes("INVALID_INPUT")) return "ข้อมูลไม่ถูกต้อง กรุณาตรวจสอบแบบฟอร์ม / Invalid input; please review the form";
  return "บันทึกงานไม่สำเร็จ กรุณาลองใหม่ / Job save failed; please try again";
}
// Map Storage upload results to the approved evidence payload shape. A string
// (local dataURL fallback) or missing path means the upload did NOT reach
// Storage — fail closed BEFORE the RPC instead of sending invalid evidence.
function mapEvidenceAttachments(attachments = []) {
  return (attachments || []).map(item => {
    if (!item || typeof item === "string" || !item.path) throw new Error("EVIDENCE_UPLOAD_FAILED");
    return {
      objectPath: item.path,
      originalName: item.originalName || "",
      mimeType: item.mimeType || "",
      sizeBytes: item.size || 0
    };
  });
}
async function createJob(payload) {
  if (!supabaseEnabled()) return createJobLocal(payload);
  if (jobMutationInFlight.create) return null;
  jobMutationInFlight.create = true;
  try {
    const result = await supabaseProvider.createJob({
      title: payload.title || payload.issueDescription,
      issueDescription: payload.issueDescription,
      roomNo: payload.roomNo,
      building: payload.building,
      floor: payload.floor,
      contactName: payload.contactName,
      contactPhone: payload.contactPhone,
      note: payload.note,
      slaNote: payload.slaNote,
      startTime: payload.startTime,
      endTime: payload.endTime,
      mainCategory: payload.mainCategory,
      category: payload.category,
      priority: payload.priority,
      jobDate: payload.jobDate,
      dueDate: payload.dueDate,
      sharePublic: payload.mainCategory === "common",
      assignee: payload.assignee || "",
      idempotencyKey: crypto.randomUUID?.() || `idem-${Date.now()}-${Math.random().toString(16).slice(2)}`
    });
    // One-time close PIN: split away from the job object at the RPC boundary.
    // It is shown once to the creator and never cached, stored or logged; the
    // rest of the RPC result is discarded — the cache refreshes via the read RPC.
    const oneTimeClosePin = result?.closePin || "";
    const createdJobId = result?.id || "";
    await loadJobsFromSupabase();
    renderAll();
    if (oneTimeClosePin) {
      alert(currentLang === "th"
        ? `PIN ปิดงาน ${createdJobId}: ${oneTimeClosePin}\nแสดงครั้งเดียวเท่านั้น กรุณาจดบันทึกและส่งต่อให้ผู้เกี่ยวข้อง`
        : `Close PIN for ${createdJobId}: ${oneTimeClosePin}\nShown once only — note it down and share with the room contact.`);
    }
    return { id: createdJobId };
  } catch (error) {
    console.warn("create_job RPC failed");
    showToast(jobMutationErrorText(error));
    return null;
  } finally {
    jobMutationInFlight.create = false;
  }
}
async function assignJob(jobId, assigneeId, extra = {}) {
  if (!supabaseEnabled()) return assignJobLocal(jobId, assigneeId, extra);
  if (jobMutationInFlight.assign) return null;
  jobMutationInFlight.assign = true;
  try {
    await supabaseProvider.assignJob(jobId, assigneeId, {
      category: extra.category,
      mainCategory: extra.mainCategory,
      note: extra.note
    });
    await loadJobsFromSupabase();
    renderAll();
    return { id: jobId };
  } catch (error) {
    console.warn("assign_job RPC failed");
    showToast(jobMutationErrorText(error));
    return null;
  } finally {
    jobMutationInFlight.assign = false;
  }
}
async function updateJobStatus(jobId, payload) {
  if (!supabaseEnabled()) return updateJobStatusLocal(jobId, payload);
  if (jobMutationInFlight.update) return { errors: ["กำลังบันทึกอยู่ กรุณารอสักครู่ / Save already in progress; please wait"] };
  jobMutationInFlight.update = true;
  try {
    // Evidence mapping happens BEFORE the RPC; invalid/failed uploads abort here.
    const evidence = mapEvidenceAttachments(payload.attachments);
    const rpcPayload = {
      status: payload.status,
      pin: payload.closePin, // server contract field is `pin`
      noPinAvailable: !!payload.noPinAvailable,
      noPinReason: payload.noPinReason,
      inspectionDate: payload.inspectionDate,
      updateDate: payload.updateDate,
      cause: payload.cause,
      solution: payload.solution,
      note: payload.note,
      completedWorkDate: payload.completedWorkDate,
      attachments: evidence
    };
    // DB-03: the key is included only when a value is present.
    if (payload.nextUpdateDate) rpcPayload.nextUpdateDate = payload.nextUpdateDate;
    await supabaseProvider.updateJobStatus(jobId, rpcPayload);
    await loadJobsFromSupabase();
    renderAll();
    return { errors: [] };
  } catch (error) {
    console.warn("update_job_status RPC failed");
    return { errors: [jobMutationErrorText(error)] };
  } finally {
    jobMutationInFlight.update = false;
  }
}
async function verifyCompletion(jobId) {
  if (!supabaseEnabled()) return verifyCompletionLocal(jobId);
  if (jobMutationInFlight.verify) return false;
  jobMutationInFlight.verify = true;
  try {
    await supabaseProvider.verifyCompletion(jobId);
    await loadJobsFromSupabase();
    renderAll();
    return true;
  } catch (error) {
    console.warn("verify_job_completion RPC failed");
    showToast(jobMutationErrorText(error));
    return false;
  } finally {
    jobMutationInFlight.verify = false;
  }
}
function createJobLocal(payload) {
  const assignee = payload.assignee ? getUser(payload.assignee) : null;
  const sequence = String(jobs.length + 1).padStart(3, "0");
  const job = normalizeJob({
    id: payload.id || `JC-260626-${sequence}`,
    source: payload.source || "WebApp",
    raw: !payload.assignee,
    title: payload.title || payload.issueDescription,
    jobDate: payload.jobDate,
    startTime: payload.startTime || "",
    endTime: payload.endTime || "",
    dueDate: payload.dueDate || "",
    slaNote: payload.slaNote || "",
    roomNo: payload.roomNo,
    room: payload.roomNo,
    building: payload.building || "",
    floor: payload.floor || "",
    contactName: payload.contactName,
    contactPhone: payload.contactPhone,
    issueDescription: payload.issueDescription,
    description: payload.issueDescription,
    initialAttachments: payload.initialAttachments || [],
    attachments: payload.initialAttachments || [],
    assignedBy: payload.assignee ? currentUser.id : "",
    assignedByName: payload.assignee ? getUserName(currentUser) : "",
    assignee: payload.assignee || null,
    assigneeName: assignee ? getUserName(assignee) : "",
    mainCategory: payload.mainCategory || "resident",
    areaType: payload.mainCategory === "common" ? "common" : "unit",
    sharePublic: payload.mainCategory === "common",
    category: payload.category || "building",
    priority: payload.priority || "normal",
    status: payload.assignee ? "received" : "open",
    subStatus: "",
    note: payload.note || "",
    closePin: generateClosePin(),
    reporter: currentUser.id,
    createdBy: currentUser.id,
    date: payload.jobDate,
    time: payload.startTime || new Date().toLocaleTimeString("th-TH", { hour: "2-digit", minute: "2-digit" }),
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    hasScheduleConflict: !!payload.hasScheduleConflict,
    conflictConfirmedAt: payload.conflictConfirmedAt || "",
    conflictConfirmedBy: payload.conflictConfirmedBy || ""
  });
  job.timeline = [];
  jobs.unshift(job);
  addJobTimeline(job.id, { action: "created", toStatus: job.status, message: `สร้างงานโดย ${getUserName(currentUser)}` });
  if (assignee) addJobTimeline(job.id, { action: "assigned", toStatus: job.status, message: `มอบหมายให้ ${getUserName(assignee)}` });
  if (job.hasScheduleConflict) addJobTimeline(job.id, { action: "schedule_conflict_confirmed", toStatus: job.status, message: `มอบหมายงานซ้อนช่วงเวลา โดยได้รับการยืนยันจาก ${getUserName(currentUser)}` });
  saveJobs();
  addLog("WEBAPP_JOB_CREATED", `New job ${job.id}${assignee ? ` assigned to ${getUserName(assignee)}` : " sent to Pool"}`);
  return job;
}
function assignJobLocal(jobId, assigneeId, extra = {}) {
  const job = normalizeJob(jobs.find(item => item.id === jobId));
  const assignee = getUser(assigneeId);
  if (!job || !assignee) return null;
  const fromStatus = job.status;
  job.raw = false;
  job.assignee = assigneeId;
  delete job.proposedAssignee;
  delete job.assignmentDeadline;
  job.assigneeName = getUserName(assignee);
  job.assignedBy = currentUser.id;
  job.assignedByName = getUserName(currentUser);
  job.category = extra.category || job.category || "building";
  job.mainCategory = extra.mainCategory || job.mainCategory || inferMainCategory(job);
  job.areaType = job.mainCategory === "common" ? "common" : "unit";
  if (job.mainCategory === "common") job.sharePublic = true;
  job.status = "received";
  job.updatedAt = new Date().toISOString();
  Object.assign(job, extra);
  addJobTimeline(job.id, { action: "assigned", fromStatus, toStatus: job.status, message: `มอบหมายให้ ${getUserName(assignee)} โดย ${getUserName(currentUser)}` });
  if (job.hasScheduleConflict) addJobTimeline(job.id, { action: "schedule_conflict_confirmed", toStatus: job.status, message: `มอบหมายงานซ้อนช่วงเวลา โดยได้รับการยืนยันจาก ${getUserName(currentUser)}` });
  saveJobs();
  addLog("JOB_ASSIGNED", `${job.id} assigned to ${getUserName(assignee)}`);
  return job;
}
function validateStatusUpdate(job, payload) {
  const errors = [];
  const status = payload.status;
  const requiresAttachment = !["received", "rejected"].includes(status);
  if (requiresAttachment && !payload.attachments?.length) errors.push("กรุณาแนบรูปอย่างน้อย 1 รูป");
  if ((payload.attachments?.length || 0) > 3) errors.push("แนบรูปได้สูงสุด 3 รูป");
  if (status === "pending_inspection" && !payload.inspectionDate) errors.push("กรุณาเลือกวันที่เข้าตรวจสอบ");
  if ((status === "repaired_follow_up" || status === "temporary_waiting_parts") && !payload.nextUpdateDate) errors.push("กรุณาเลือกวันที่อัปเดต/ติดตามครั้งถัดไป");
  if (status === "inspected_waiting_repair") {
    if (!payload.updateDate) errors.push("กรุณาเลือกวันที่ตรวจสอบ / วันที่อัปเดต");
    if (!payload.cause) errors.push("กรุณากรอกสาเหตุ");
    if (!payload.solution) errors.push("กรุณากรอกแนวทางแก้ไข");
  }
  if (status === "completed") {
    if (payload.noPinAvailable) {
      if (!payload.noPinReason) errors.push("กรุณากรอกเหตุผลที่ไม่มี PIN");
      if (!payload.attachments?.length) errors.push("กรุณาแนบรูปอย่างน้อย 1 รูปเมื่อไม่มี PIN");
    } else if (payload.closePin !== job.closePin) errors.push("PIN ไม่ถูกต้อง");
  }
  if (payload.attachments?.some(file => file.size && file.size > 5 * 1024 * 1024)) errors.push("รูปภาพต้องมีขนาดไม่เกิน 5MB ต่อไฟล์");
  return errors;
}
function updateJobStatusLocal(jobId, payload) {
  const job = normalizeJob(jobs.find(item => item.id === jobId));
  if (!job) return { errors: ["ไม่พบงาน"] };
  const errors = validateStatusUpdate(job, payload);
  if (errors.length) return { errors };
  const fromStatus = job.status;
  const now = new Date().toISOString();
  if (payload.status === "completed" && payload.noPinAvailable) {
    job.status = "pending_inspection";
    job.subStatus = "waiting_owner_or_admin_verification";
    job.noPinAvailable = true;
    job.noPinReason = payload.noPinReason;
    job.pendingVerificationAt = now;
    job.completedAt = "";
  } else {
    job.status = payload.status;
    job.subStatus = "";
    if (payload.status === "completed") {
      job.completedAt = now;
      job.completedWorkDate = payload.completedWorkDate || now.slice(0, 10);
    }
  }
  if (payload.status === "received") job.acceptedAt = now;
  if (payload.status === "pending_inspection" && payload.inspectionDate) job.inspectionDate = payload.inspectionDate;
  if ((payload.status === "repaired_follow_up" || payload.status === "temporary_waiting_parts") && payload.nextUpdateDate) job.nextUpdateDate = payload.nextUpdateDate;
  if (payload.status === "inspected_waiting_repair") {
    job.inspectionDate = payload.updateDate;
    job.cause = payload.cause;
    job.solution = payload.solution;
  }
  job.note = payload.note || job.note || "";
  if (payload.attachments?.length) job.attachments = [...(job.attachments || []), ...payload.attachments];
  job.statusUpdates = job.statusUpdates || [];
  job.statusUpdates.unshift({ at: now, by: currentUser.id, byName: getUserName(currentUser), ...payload, attachmentsCount: payload.attachments?.length || 0 });
  addJobTimeline(job.id, {
    action: payload.noPinAvailable ? "complete_without_pin" : "status_update",
    fromStatus,
    toStatus: job.status,
    message: payload.noPinAvailable
      ? `ช่างแจ้งว่าแก้ไขงานเสร็จแล้ว แต่ไม่สามารถขอ PIN ได้ เนื่องจาก ${payload.noPinReason}`
      : `เปลี่ยนสถานะเป็น ${statusLabel(job.status)} โดย ${getUserName(currentUser)}${payload.cause ? ` สาเหตุ: ${payload.cause} แนวทางแก้ไข: ${payload.solution}` : ""}`,
    data: { subStatus: job.subStatus, noPinAvailable: job.noPinAvailable, attachmentsCount: payload.attachments?.length || 0 }
  });
  saveJobs();
  addLog("JOB_UPDATED", `${job.id} updated to ${statusLabel(job.status, job.subStatus)}`);
  return { job, errors: [] };
}
function verifyCompletionLocal(jobId) {
  const job = normalizeJob(jobs.find(item => item.id === jobId));
  if (!canVerifyCompletion(currentUser, job)) return false;
  const fromStatus = job.status;
  job.status = "completed";
  job.subStatus = "";
  job.completedAt = new Date().toISOString();
  job.completedWorkDate = job.completedWorkDate || job.completedAt.slice(0, 10);
  addJobTimeline(job.id, { action: "verified_completed", fromStatus, toStatus: "completed", message: `ยืนยันปิดงานโดย ${getUserName(currentUser)}` });
  saveJobs();
  addLog("JOB_COMPLETION_VERIFIED", `${job.id} verified completed by ${getUserName(currentUser)}`);
  return true;
}
function getDashboardCounts(scopeJobs = jobs.filter(job => canViewJob(currentUser, normalizeJob(job)))) {
  const normalized = scopeJobs.map(normalizeJob).filter(Boolean);
  return {
    open: normalized.filter(job => normalizeStatus(job.status) === "open").length,
    received: normalized.filter(job => normalizeStatus(job.status) === "received").length,
    pendingInspection: normalized.filter(job => normalizeStatus(job.status) === "pending_inspection" && job.subStatus !== "waiting_owner_or_admin_verification").length,
    inspectedWaitingRepair: normalized.filter(job => normalizeStatus(job.status) === "inspected_waiting_repair").length,
    repairedFollowUp: normalized.filter(job => normalizeStatus(job.status) === "repaired_follow_up").length,
    temporaryWaitingParts: normalized.filter(job => normalizeStatus(job.status) === "temporary_waiting_parts").length,
    waitingVerification: normalized.filter(job => job.subStatus === "waiting_owner_or_admin_verification").length,
    completed: normalized.filter(job => normalizeStatus(job.status) === "completed" && job.completedAt).length,
    rejected: normalized.filter(job => normalizeStatus(job.status) === "rejected").length,
    conflict: normalized.filter(job => job.hasScheduleConflict).length,
    noPin: normalized.filter(job => job.noPinAvailable).length
  };
}
function todayIso() {
  return new Date().toISOString().slice(0, 10);
}
function addDaysIso(days) {
  const date = new Date();
  date.setDate(date.getDate() + days);
  return date.toISOString().slice(0, 10);
}
function addDaysFromIso(iso, days) {
  const date = iso ? new Date(`${iso}T00:00:00`) : new Date();
  date.setDate(date.getDate() + days);
  return date.toISOString().slice(0, 10);
}
function defaultDueDate(job = {}) {
  const base = job.jobDate || job.date || todayIso();
  const days = job.priority === "urgent" ? 1 : job.priority === "high" ? 3 : 7;
  return addDaysFromIso(base, days);
}
function dueInfo(job = {}) {
  job = normalizeJob(job);
  if (!job.dueDate || ["completed", "rejected"].includes(normalizeStatus(job.status))) {
    return { state: "done", label: currentLang === "th" ? "ไม่มี SLA ค้าง" : "No active SLA", days: 0 };
  }
  const today = todayIso();
  const due = new Date(`${job.dueDate}T00:00:00`);
  const now = new Date(`${today}T00:00:00`);
  const days = Math.round((due - now) / 86400000);
  if (days < 0) return { state: "overdue", days, label: currentLang === "th" ? `เกินกำหนด ${Math.abs(days)} วัน` : `${Math.abs(days)} days overdue` };
  if (days === 0) return { state: "today", days, label: currentLang === "th" ? "ครบกำหนดวันนี้" : "Due today" };
  if (days <= 2) return { state: "soon", days, label: currentLang === "th" ? `เหลือ ${days} วัน` : `${days} days left` };
  return { state: "normal", days, label: currentLang === "th" ? `เหลือ ${days} วัน` : `${days} days left` };
}
function isJobInDashboardRange(job) {
  job = normalizeJob(job);
  const jobDate = job.jobDate || job.date || job.createdAt?.slice(0, 10) || todayIso();
  const today = todayIso();
  if (dashboardRange === "today") return jobDate === today;
  const days = Number(dashboardRange) || 7;
  return jobDate >= addDaysIso(-(days - 1)) && jobDate <= today;
}
function getDashboardRangeJobs(view = "dashboard") {
  return getViewJobs(view).filter(isJobInDashboardRange);
}
function dashboardRangeLabel() {
  if (dashboardRange === "today") return currentLang === "th" ? "วันนี้" : "today";
  return currentLang === "th" ? `${dashboardRange} วัน` : `${dashboardRange} days`;
}
function getNotifications() {
  if (!currentUser) return [];
  const today = todayIso();
  return jobs.map(normalizeJob).filter(job => canViewJob(currentUser, job)).flatMap(job => {
    const items = [];
    const due = dueInfo(job);
    if (due.state === "overdue") items.push({ type: "overdue", job, label: due.label });
    else if (due.state === "today" || due.state === "soon") items.push({ type: "due", job, label: due.label });
    if (job.raw || (!job.assignee && normalizeStatus(job.status) === "open")) items.push({ type: "pool", job, label: currentLang === "th" ? "งานใหม่รอมอบหมาย" : "New job waiting assignment" });
    if (job.nextUpdateDate && job.nextUpdateDate <= today && !["completed", "rejected"].includes(normalizeStatus(job.status))) items.push({ type: "follow", job, label: currentLang === "th" ? "ถึงกำหนดติดตาม/อัปเดต" : "Follow-up due" });
    if (job.hasScheduleConflict) items.push({ type: "conflict", job, label: currentLang === "th" ? "มีเวลางานซ้อน" : "Schedule conflict" });
    if (job.subStatus === "waiting_owner_or_admin_verification") items.push({ type: "verify", job, label: currentLang === "th" ? "รอตรวจสอบยืนยันปิดงาน" : "Waiting close verification" });
    return items;
  }).slice(0, 20);
}
function renderNotifications() {
  const notifications = getNotifications();
  $("#notificationCount").textContent = notifications.length;
  $(".notification-btn")?.classList.toggle("has-alert", notifications.length > 0);
  const panel = $("#notificationPanel");
  if (!panel) return;
  panel.innerHTML = `<div class="notification-head"><strong>${currentLang === "th" ? "การแจ้งเตือน" : "Notifications"}</strong><small>${notifications.length} ${currentLang === "th" ? "รายการ" : "items"}</small></div>` +
    (notifications.length ? notifications.map(item => `<button type="button" class="notification-item" data-job-id="${item.job.id}">
      <span class="notification-type">${esc(item.label)}</span>
      <strong>${esc(getText(item.job.title))}</strong>
      <small>${esc(item.job.id)} · ${formatDate(item.job.jobDate)} · ${statusLabel(item.job.status, item.job.subStatus)}</small>
    </button>`).join("") : `<div class="notification-empty">${currentLang === "th" ? "ยังไม่มีรายการที่ต้องติดตาม" : "No alerts right now"}</div>`);
}
function getReportCounts(scopeJobs = jobs) {
  const counts = getDashboardCounts(scopeJobs);
  return {
    total: scopeJobs.length,
    open: counts.open,
    inProgress: counts.received + counts.pendingInspection + counts.inspectedWaitingRepair + counts.repairedFollowUp + counts.temporaryWaitingParts,
    waitingVerification: counts.waitingVerification,
    realCompleted: counts.completed,
    rejected: counts.rejected
  };
}
function inferDepartment(user) {
  if (user.department) return user.department;
  if (user.role === "resident") return "resident";
  if (user.team === "cleaning") return "housekeeping";
  if (user.team === "security") return "security_staff";
  if (user.team === "garden") return "gardener";
  if (user.team) return "technician";
  return user.canAssign ? "juristic" : "juristic";
}

function saveJobs() {
  // Stage 3: in Supabase mode jobs are never persisted locally or synced via
  // snapshot — the relational database is the only job authority and the
  // in-memory array is a render cache for the current session.
  if (supabaseEnabled()) return;
  localStorage.setItem("juristicJobsV2", JSON.stringify(jobs));
  queueBackendSync();
}
