function saveTeamOverrides() { localStorage.setItem("juristicTeamOverrides", JSON.stringify(teamOverrides)); queueBackendSync(); }
function saveCustomUsers() { localStorage.setItem("juristicCustomUsers", JSON.stringify(customUsers)); queueBackendSync(); }
function saveDeletedUsers() { localStorage.setItem("juristicDeletedUsers", JSON.stringify(deletedUserIds)); queueBackendSync(); }
