function isPdfAnnouncement(item) {
  const firstPage = mediaSrc(item?.pages?.[0] || "");
  return item?.type === "pdf" || firstPage.startsWith("data:application/pdf") || firstPage.includes(".pdf");
}
function isRealPdfSource(src = "") {
  return String(src).startsWith("data:application/pdf") || /\.pdf($|[?#])/i.test(String(src));
}
function isLegacyPdfPlaceholder(item, src = "") {
  return isPdfAnnouncement(item) && !isRealPdfSource(src);
}
function announcementTypeLabel(item) {
  if (isPdfAnnouncement(item)) return "PDF";
  if (item?.type === "document") return "DOC";
  return "IMG";
}
function announcementFirstPage(item) {
  return mediaSrc(item?.pages?.[0]) || photo("ANN", "#0f766e");
}
function announcementPreviewMarkup(item, className = "announcement-preview") {
  const src = announcementFirstPage(item);
  if (isPdfAnnouncement(item) && isRealPdfSource(src)) {
    const pdfSrc = `${src}#page=1&toolbar=0&navpanes=0&scrollbar=0`;
    return `<object class="${className} pdf-preview" data="${pdfSrc}" type="application/pdf" aria-label="${esc(getText(item.title))}">
      <a href="${src}" target="_blank" rel="noreferrer">${currentLang === "th" ? "เปิดไฟล์ PDF" : "Open PDF"}</a>
    </object>`;
  }
  if (isLegacyPdfPlaceholder(item, src)) {
    return `<div class="${className} announcement-pdf-missing">
      <strong>PDF</strong>
      <span>${currentLang === "th" ? "ไฟล์นี้ถูกอัปโหลดก่อนระบบเก็บต้นฉบับ PDF กรุณาอัปโหลดไฟล์ใหม่เพื่อแสดงหน้าแรกและดาวน์โหลด" : "This file was uploaded before original PDF storage was enabled. Please re-upload it to preview and download."}</span>
    </div>`;
  }
  return `<img class="${className}" src="${src}" alt="${esc(getText(item.title))}">`;
}
function dataUrlToBlob(src = "") {
  const match = String(src).match(/^data:([^;,]+)?(;base64)?,(.*)$/);
  if (!match) return null;
  const mime = match[1] || "application/octet-stream";
  const isBase64 = Boolean(match[2]);
  const data = match[3] || "";
  const binary = isBase64 ? atob(data) : decodeURIComponent(data);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return new Blob([bytes], { type: mime });
}
function fileExtensionFromDataUrl(src = "") {
  const mime = String(src).match(/^data:([^;,]+)/)?.[1] || "";
  if (!mime && /\.pdf($|[?#])/i.test(String(src))) return "pdf";
  if (mime.includes("pdf")) return "pdf";
  if (mime.includes("png")) return "png";
  if (mime.includes("jpeg") || mime.includes("jpg")) return "jpg";
  if (mime.includes("webp")) return "webp";
  if (mime.includes("svg")) return "svg";
  return "file";
}
function safeFileName(name = "announcement") {
  return String(name || "announcement").trim().replace(/[\\/:*?"<>|]+/g, "-").replace(/\s+/g, "-").slice(0, 80) || "announcement";
}
function revokeActiveAnnouncementDownloadUrl() {
  if (!activeAnnouncementDownloadUrl) return;
  URL.revokeObjectURL(activeAnnouncementDownloadUrl);
  activeAnnouncementDownloadUrl = "";
}
function announcementDownloadInfo(item, page) {
  const src = mediaSrc(item?.pages?.[page]) || announcementFirstPage(item);
  if (!src) return null;
  if (isLegacyPdfPlaceholder(item, src)) {
    revokeActiveAnnouncementDownloadUrl();
    return { legacy: true, href: "#", filename: "" };
  }
  const blob = String(src).startsWith("data:") ? dataUrlToBlob(src) : null;
  if (blob) {
    const href = URL.createObjectURL(blob);
    revokeActiveAnnouncementDownloadUrl();
    activeAnnouncementDownloadUrl = href;
    return {
      legacy: false,
      href,
      filename: `${safeFileName(getText(item.title))}-page-${page + 1}.${fileExtensionFromDataUrl(src)}`
    };
  }
  revokeActiveAnnouncementDownloadUrl();
  return {
    legacy: false,
    href: src,
    filename: `${safeFileName(getText(item.title))}-page-${page + 1}.${fileExtensionFromDataUrl(src)}`
  };
}
function downloadActiveAnnouncementPage() {
  const item = announcements[activeAnnouncementIndex];
  if (!item) return;
  const src = mediaSrc(item.pages?.[activeAnnouncementPage]) || announcementFirstPage(item);
  if (!src) return;
  if (isLegacyPdfPlaceholder(item, src)) {
    showToast(currentLang === "th" ? "ไฟล์ PDF เดิมไม่ได้เก็บต้นฉบับไว้ กรุณาอัปโหลดใหม่" : "Original PDF was not stored. Please re-upload it.");
    return;
  }
  const link = $("#announcementDownloadLink");
  if (link?.href && link.getAttribute("href") !== "#") link.click();
}
