function canImportFinance() { return currentUser?.role === "admin" || hasActionPermission("importExport") || currentUser?.role === "staff" || inferDepartment(currentUser) === "committee"; }
function downloadTextFile(filename, content, mime = "text/plain;charset=utf-8") {
  const blob = new Blob([content], { type: mime });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  URL.revokeObjectURL(a.href);
  a.remove();
}
function jobTimelineRows(job) {
  job = normalizeJob(job);
  const timelineRows = (job.timeline || []).map(log => ({
    at: log.at,
    by: log.byName || "",
    action: log.action || "",
    status: statusLabel(log.toStatus || job.status, log.data?.subStatus || ""),
    message: log.message || "",
    attachments: []
  }));
  const updateRows = (job.statusUpdates || []).map(update => ({
    at: update.at,
    by: update.byName || "",
    action: "status_update",
    status: statusLabel(update.status || job.status, update.subStatus || ""),
    message: [update.note, update.cause, update.solution, update.noPinReason].filter(Boolean).join(" · "),
    attachments: update.attachments || []
  }));
  const initialRows = (job.initialAttachments || []).length ? [{
    at: job.createdAt,
    by: job.contactName || getUserName(getUser(job.reporter)) || "Reporter",
    action: "initial_photos",
    status: statusLabel(job.status, job.subStatus),
    message: currentLang === "th" ? "รูปภาพตอนเปิดงาน" : "Initial report photos",
    attachments: job.initialAttachments || []
  }] : [];
  return [...initialRows, ...updateRows, ...timelineRows].sort((a, b) => new Date(a.at) - new Date(b.at));
}
function exportJobCsv(jobId) {
  const job = normalizeJob(jobs.find(item => item.id === jobId));
  if (!job) return;
  const assignee = getUser(job.assignee);
  const reporter = getUser(job.reporter);
  const due = dueInfo(job);
  const headers = ["job_id", "title", "source", "status", "main_category", "sub_category", "priority", "room", "building", "floor", "contact_name", "contact_phone", "reporter", "assignee", "assigned_by", "job_date", "due_date", "due_status", "next_update_date", "description", "timeline_at", "timeline_by", "timeline_action", "timeline_status", "timeline_message", "attachment_count", "attachment_refs"];
  const base = [
    job.id, getText(job.title), job.source || "", statusLabel(job.status, job.subStatus), mainCategoryLabel(job.mainCategory),
    categoryLabel(job.category), priorityLabel(job.priority), job.roomNo || getText(job.room), job.building || "", job.floor || "",
    job.contactName || "", job.contactPhone || "", reporter ? getUserName(reporter) : "", assignee ? getUserName(assignee) : "",
    job.assignedByName || getUserName(getUser(job.assignedBy)) || "", job.jobDate || "", job.dueDate || "", due.label,
    job.nextUpdateDate || "", job.issueDescription || getText(job.description) || ""
  ];
  const rows = jobTimelineRows(job).map((row, rowIndex) => [
    ...base,
    row.at || "", row.by || "", row.action || "", row.status || "", row.message || "",
    row.attachments?.length || 0,
    (row.attachments || []).map((_, index) => `timeline_${rowIndex + 1}_image_${index + 1}`).join(";")
  ]);
  const csv = [headers, ...(rows.length ? rows : [[...base, "", "", "", "", "", 0, ""]])].map(csvLine).join("\n");
  downloadTextFile(`${job.id}-tracking-report.csv`, "\ufeff" + csv, "text/csv;charset=utf-8");
  addLog("JOB_EXPORTED_CSV", `${job.id} exported to CSV by ${getUserName(currentUser)}`);
}
