const sidebarOrderKey = (user = currentUser) => `juristicSidebarOrderV2:${user?.id || "default"}`;
const defaultSidebarOrder = () => [
  "googleForms",
  "dashboard",
  "myjobs",
  "commonWork",
  "residentWork",
  "finance",
  "calendar",
  "pool",
  "staffJobs",
  "roomjobs",
  "backoffice",
  ...backofficeChildKeys
];
function savedSidebarOrder(user = currentUser) {
  try {
    const saved = JSON.parse(localStorage.getItem(sidebarOrderKey(user)) || "null");
    return Array.isArray(saved) ? saved : defaultSidebarOrder();
  } catch {
    return defaultSidebarOrder();
  }
}
function orderedSidebarItems(user = currentUser) {
  const visible = permissionSidebarItems.filter(item => hasSidebarAccess(item.view, user));
  const order = savedSidebarOrder(user);
  return [...visible].sort((a, b) => {
    const ai = order.indexOf(a.key);
    const bi = order.indexOf(b.key);
    return (ai === -1 ? 999 : ai) - (bi === -1 ? 999 : bi);
  });
}
function renderAccountNavMenu() {
  const target = $("#accountNavMenu");
  if (!target || !currentUser) return;
  const items = orderedSidebarItems();
  target.innerHTML = `
    <div class="account-menu-title">${currentLang === "th" ? "เมนูระบบ" : "System menu"}</div>
    ${items.map(item => `
      <button type="button" class="account-nav-item ${currentView === item.view ? "active" : ""}" data-view="${item.view}">
        <span>${item.icon}</span><strong>${permissionLabel(item)}</strong>
      </button>`).join("")}
  `;
}
function syncNavigationOrder() {
  if (!currentUser) return;
  const items = orderedSidebarItems();
  const topItems = items.filter(item => item.key !== "backoffice" && !isBackofficeChild(item));
  const backofficeItems = items.filter(isBackofficeChild);
  const mainNav = $(".main-nav");
  if (mainNav) {
    topItems.forEach(item => {
      const button = mainNav.querySelector(`[data-view='${item.view}']`);
      if (button) mainNav.appendChild(button);
    });
    const group = mainNav.querySelector("[data-sidebar-group='backoffice']");
    const subnav = $("#backofficeSubnav");
    if (group) mainNav.appendChild(group);
    if (subnav) {
      backofficeItems.forEach(item => {
        const button = subnav.querySelector(`[data-view='${item.view}']`) || mainNav.querySelector(`[data-view='${item.view}']`);
        if (button) subnav.appendChild(button);
      });
    }
  }
  const mobileNav = $(".mobile-bottom-nav");
  if (mobileNav) {
    [...topItems, ...backofficeItems].forEach(item => {
      const button = mobileNav.querySelector(`[data-view='${item.view}']`);
      if (button) mobileNav.appendChild(button);
    });
  }
  renderAccountNavMenu();
}
function renderSidebarManageModal() {
  const list = $("#sidebarManageList");
  if (!list || !currentUser) return;
  const visibleKeys = orderedSidebarItems().map(item => item.key);
  draftSidebarOrder = (draftSidebarOrder.length ? draftSidebarOrder : savedSidebarOrder()).filter(key => visibleKeys.includes(key));
  visibleKeys.forEach(key => { if (!draftSidebarOrder.includes(key)) draftSidebarOrder.push(key); });
  list.innerHTML = draftSidebarOrder.map((key, index) => {
    const item = permissionSidebarItems.find(entry => entry.key === key);
    if (!item) return "";
    return `<div class="sidebar-manage-row">
      <span>${item.icon}</span>
      <strong>${permissionLabel(item)}</strong>
      <div>
        <button type="button" class="secondary-btn" data-sidebar-order-move="up" data-sidebar-key="${item.key}" ${index === 0 ? "disabled" : ""}>ขึ้น</button>
        <button type="button" class="secondary-btn" data-sidebar-order-move="down" data-sidebar-key="${item.key}" ${index === draftSidebarOrder.length - 1 ? "disabled" : ""}>ลง</button>
      </div>
    </div>`;
  }).join("");
}
function openSidebarManageModal() {
  draftSidebarOrder = savedSidebarOrder().filter(key => orderedSidebarItems().some(item => item.key === key));
  renderSidebarManageModal();
  $("#sidebarManageModal")?.classList.remove("hidden");
}
function moveSidebarDraft(key, direction) {
  const index = draftSidebarOrder.indexOf(key);
  if (index === -1) return;
  const target = direction === "up" ? index - 1 : index + 1;
  if (!draftSidebarOrder[target]) return;
  [draftSidebarOrder[index], draftSidebarOrder[target]] = [draftSidebarOrder[target], draftSidebarOrder[index]];
  renderSidebarManageModal();
}
function saveSidebarOrder() {
  const visibleKeys = orderedSidebarItems().map(item => item.key);
  const next = draftSidebarOrder.filter(key => visibleKeys.includes(key));
  visibleKeys.forEach(key => { if (!next.includes(key)) next.push(key); });
  localStorage.setItem(sidebarOrderKey(), JSON.stringify(next));
  queueBackendSync();
  if (supabaseEnabled()) supabaseProvider.saveSidebarOrder(currentUser.id, next).catch(error => console.warn("Sidebar order save failed", error));
  syncNavigationOrder();
  $("#sidebarManageModal")?.classList.add("hidden");
  addLog("SIDEBAR_ORDER_SAVED", `${getUserName(currentUser)} saved sidebar order`);
  showToast(currentLang === "th" ? "บันทึกการตั้งค่าแถบหมวดหมู่แล้ว" : "Sidebar settings saved");
}
function resetSidebarOrder() {
  localStorage.removeItem(sidebarOrderKey());
  draftSidebarOrder = orderedSidebarItems().map(item => item.key);
  renderSidebarManageModal();
  syncNavigationOrder();
  addLog("SIDEBAR_ORDER_RESET", `${getUserName(currentUser)} reset sidebar order`);
  showToast(currentLang === "th" ? "คืนค่าเริ่มต้นแล้ว กดบันทึกเพื่อยืนยันลำดับนี้" : "Default order restored. Save to confirm.");
}
function setupRoleMenu() {
  const isAdmin = currentUser.role === "admin";
  const isResident = currentUser.role === "resident";
  const teamManager = canManageTeam();
  const residentWorkAllowed = canViewResidentWork();
  ensureBackhouseNav();
  ensureBackhouseView();
  ensureOrganizationNav();
  ensureOrganizationView();
  ensurePermissionNav();
  ensurePermissionView();
  $$(".admin-only").forEach(el => el.classList.toggle("hidden", !isAdmin));
  $$(".manage-team-only").forEach(el => el.classList.toggle("hidden", !teamManager));
  $("#adminViewSwitch")?.classList.toggle("hidden", !(isAdmin && !isAdminPreviewMode()));
  $("#exitAdminPreviewBtn")?.classList.toggle("hidden", !isAdminPreviewMode());
  permissionSidebarItems.forEach(item => {
    $$(`[data-view='${item.view}']`).forEach(el => el.classList.toggle("hidden", !hasSidebarAccess(item.view)));
  });
  const backofficeGroup = $("[data-sidebar-group='backoffice']");
  const hasBackofficeChildren = backofficeChildKeys.some(key => {
    const item = permissionSidebarItems.find(entry => entry.key === key);
    return item && hasSidebarAccess(item.view);
  });
  backofficeGroup?.classList.toggle("hidden", !(hasSidebarAccess("backoffice") && hasBackofficeChildren));
  $$("[data-view='juristicTeam'], [data-view='technicianJobs'], [data-view='housekeepingJobs'], [data-view='staffLogs']").forEach(el => el.classList.add("hidden"));
  $$("#createJobBtn, #mobileCreateJobBtn").forEach(el => el.classList.toggle("hidden", !hasActionPermission("createJob")));
  if (isResident) {
    $$("[data-view='dashboard'] [data-i18n], [data-view='dashboard'] small").forEach(el => el.textContent = currentLang === "th" ? "ภาพรวม" : "Overview");
    $$("[data-view='roomjobs'] [data-i18n], [data-view='roomjobs'] small").forEach(el => el.textContent = currentLang === "th" ? "ห้องของฉัน" : "My Room");
  }
}
async function showApp(user) {
  currentUser = user;
  $("#authView").classList.add("hidden");
  $("#appView").classList.remove("hidden");
  setupRoleMenu();
  updateUserChrome();
  updateCurrentDate();
  sessionStorage.setItem("juristicUser", user.id);
  if (user.role === "admin") addLog("ADMIN_LOGIN", `${getUserName(user)} signed in`, user);
  else if (user.isCoAdmin) addLog("CO_ADMIN_LOGIN", `${getUserName(user)} signed in`, user);
  else if (user.role === "staff") addLog("STAFF_LOGIN", `${getUserName(user)} signed in`, user);
  else if (user.role === "resident") addLog("RESIDENT_LOGIN", `${getUserName(user)} (${user.room}) signed in`, user);
  populateControls();
  renderAll();
  await loadBackendSnapshot();
  navigate("dashboard");
  openInterfacePicker();
}
