function selectedCalendarEvent() {
  return calendarEvents.find(item => item.id === selectedCalendarEventId) || calendarEvents[0];
}
function selectedVisibleCalendarEvent() {
  const item = calendarEvents.find(event => event.id === selectedCalendarEventId);
  if (!item) return null;
  const date = new Date(`${item.date}T00:00:00`);
  return date.getMonth() === selectedCalendarMonth && date.getFullYear() === selectedCalendarYear ? item : null;
}
function calendarEventsForDay(day) {
  return calendarEvents
    .filter(item => {
      const date = new Date(`${item.date}T00:00:00`);
      return item.day === Number(day) && date.getMonth() === selectedCalendarMonth && date.getFullYear() === selectedCalendarYear;
    })
    .sort((a, b) => a.time.localeCompare(b.time));
}
function todayCalendarEvents() {
  return calendarEventsForDay(27);
}
function upcomingCalendarEvents(limit = 5) {
  return calendarEvents
    .filter(item => item.day >= 27)
    .sort((a, b) => a.date.localeCompare(b.date) || a.time.localeCompare(b.time))
    .slice(0, limit);
}
function calendarMonthName() {
  return new Intl.DateTimeFormat(currentLang === "th" ? "th-TH" : "en-US", { month: "long" }).format(new Date(selectedCalendarYear, selectedCalendarMonth, 1));
}
function calendarMonthNameAt(month) {
  return new Intl.DateTimeFormat(currentLang === "th" ? "th-TH" : "en-US", { month: "short" }).format(new Date(selectedCalendarYear, month, 1));
}
function calendarYearLabel() {
  const year = currentLang === "th" ? selectedCalendarYear + 543 : selectedCalendarYear;
  return String(year);
}
function calendarYearOptionLabel(year) {
  return String(currentLang === "th" ? year + 543 : year);
}
function calendarPickerHtml() {
  if (calendarPickerMode === "month") {
    return `<div class="calendar-picker">${Array.from({ length: 12 }, (_, month) => `<button type="button" class="${month === selectedCalendarMonth ? "active" : ""}" data-calendar-month-option="${month}">${calendarMonthNameAt(month)}</button>`).join("")}</div>`;
  }
  if (calendarPickerMode === "year") {
    const start = selectedCalendarYear - 2;
    return `<div class="calendar-picker year-picker">${Array.from({ length: 7 }, (_, offset) => start + offset).map(year => `<button type="button" class="${year === selectedCalendarYear ? "active" : ""}" data-calendar-year-option="${year}">${calendarYearOptionLabel(year)}</button>`).join("")}</div>`;
  }
  return "";
}
function daysInSelectedMonth() {
  return new Date(selectedCalendarYear, selectedCalendarMonth + 1, 0).getDate();
}
function setCalendarMonthYear(month, year) {
  selectedCalendarMonth = Math.max(0, Math.min(11, Number(month)));
  selectedCalendarYear = Math.max(2000, Math.min(2100, Number(year)));
  const maxDay = daysInSelectedMonth();
  selectedCalendarDay = Math.min(selectedCalendarDay, maxDay);
  localStorage.setItem("juristicSelectedCalendarMonth", String(selectedCalendarMonth));
  localStorage.setItem("juristicSelectedCalendarYear", String(selectedCalendarYear));
  localStorage.setItem("juristicSelectedCalendarDay", String(selectedCalendarDay));
  const firstEvent = calendarEventsForDay(selectedCalendarDay)[0] || calendarEvents.find(item => {
    const date = new Date(`${item.date}T00:00:00`);
    return date.getMonth() === selectedCalendarMonth && date.getFullYear() === selectedCalendarYear;
  });
  if (firstEvent) {
    selectedCalendarEventId = firstEvent.id;
    selectedCalendarDay = firstEvent.day;
    localStorage.setItem("juristicSelectedCalendarEvent", selectedCalendarEventId);
    localStorage.setItem("juristicSelectedCalendarDay", String(selectedCalendarDay));
  }
}
function shiftCalendarMonth(delta) {
  const date = new Date(selectedCalendarYear, selectedCalendarMonth + delta, 1);
  setCalendarMonthYear(date.getMonth(), date.getFullYear());
  renderCalendar();
}
function goToTodayCalendar() {
  const now = new Date();
  selectedCalendarMonth = now.getMonth();
  selectedCalendarYear = now.getFullYear();
  selectedCalendarDay = now.getDate();
  localStorage.setItem("juristicSelectedCalendarMonth", String(selectedCalendarMonth));
  localStorage.setItem("juristicSelectedCalendarYear", String(selectedCalendarYear));
  localStorage.setItem("juristicSelectedCalendarDay", String(selectedCalendarDay));
  const firstEvent = calendarEventsForDay(selectedCalendarDay)[0];
  if (firstEvent) {
    selectedCalendarEventId = firstEvent.id;
    localStorage.setItem("juristicSelectedCalendarEvent", selectedCalendarEventId);
  }
  renderCalendar();
}
function promptCalendarMonth() {
  const value = prompt(currentLang === "th" ? "เลือกเดือน (1-12)" : "Choose month (1-12)", String(selectedCalendarMonth + 1));
  if (!value) return;
  const month = Number(value) - 1;
  if (Number.isInteger(month) && month >= 0 && month <= 11) {
    setCalendarMonthYear(month, selectedCalendarYear);
    renderCalendar();
  } else {
    showToast(currentLang === "th" ? "กรุณาระบุเดือน 1-12" : "Please enter month 1-12");
  }
}
function promptCalendarYear() {
  const value = prompt(currentLang === "th" ? "เลือกปี ค.ศ. เช่น 2026" : "Choose year, e.g. 2026", String(selectedCalendarYear));
  if (!value) return;
  const year = Number(value);
  if (Number.isInteger(year) && year >= 2000 && year <= 2100) {
    setCalendarMonthYear(selectedCalendarMonth, year);
    renderCalendar();
  } else {
    showToast(currentLang === "th" ? "กรุณาระบุปี ค.ศ. 2000-2100" : "Please enter year 2000-2100");
  }
}
function icsDateTime(event) {
  return `${event.date.replaceAll("-", "")}T${event.time.replace(":", "")}00`;
}
function buildCalendarIcs() {
  const stamp = new Date().toISOString().replace(/[-:]/g, "").split(".")[0] + "Z";
  const events = calendarEvents.map(event => [
    "BEGIN:VEVENT",
    `UID:${event.id}@juristic-care.local`,
    `DTSTAMP:${stamp}`,
    `DTSTART:${icsDateTime(event)}`,
    `DTEND:${icsDateTime({ ...event, time: event.time.replace(/(\d{2}):(\d{2})/, (_, h, m) => `${String(Math.min(Number(h) + 1, 23)).padStart(2, "0")}:${m}`) })}`,
    `SUMMARY:${getText(event.title)}`,
    `LOCATION:${getText(event.location)}`,
    `DESCRIPTION:${getText(event.detail)}`,
    "END:VEVENT"
  ].join("\r\n")).join("\r\n");
  return ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//Juristic Care//Calendar Mockup//TH", "CALSCALE:GREGORIAN", "METHOD:PUBLISH", events, "END:VCALENDAR"].join("\r\n");
}
async function shareCalendarToPhone() {
  const fileName = "juristic-care-calendar.ics";
  const ics = buildCalendarIcs();
  const blob = new Blob([ics], { type: "text/calendar;charset=utf-8" });
  if (typeof File !== "undefined" && navigator.share && navigator.canShare) {
    const file = new File([blob], fileName, { type: "text/calendar" });
    try {
      if (navigator.canShare({ files: [file] })) {
        await navigator.share({
          title: "Juristic Care Calendar",
          text: currentLang === "th" ? "เพิ่มปฏิทินนิติบุคคลลงโทรศัพท์" : "Add Juristic Care calendar to your phone",
          files: [file]
        });
        showToast(currentLang === "th" ? "เปิดหน้าต่างแชร์ปฏิทินแล้ว" : "Calendar share sheet opened");
        return;
      }
    } catch (error) {}
  }
  downloadTextFile(fileName, ics, "text/calendar;charset=utf-8");
  showToast(currentLang === "th" ? "ดาวน์โหลดไฟล์ .ics สำหรับเพิ่มเข้า Calendar แล้ว" : "Downloaded .ics calendar file");
}
function renderCalendar() {
  const selected = selectedVisibleCalendarEvent();
  const eventByDay = new Map(calendarEvents.map(item => [item.day, calendarEventsForDay(item.day)]));
  const maxDay = daysInSelectedMonth();
  const cells = Array.from({ length: 35 }, (_, i) => {
    const day = i + 1;
    if (day > maxDay) return `<span></span>`;
    const dayEvents = eventByDay.get(day) || [];
    const isToday = day === 27 && selectedCalendarMonth === 5 && selectedCalendarYear === 2026;
    const classes = [isToday ? "today" : "", dayEvents.length ? "has-event" : "", day === selectedCalendarDay ? "selected-event" : ""].filter(Boolean).join(" ");
    return `<button class="${classes}" type="button" data-calendar-day="${day}"><strong>${day}</strong>${dayEvents.length ? `<small>${dayEvents.length} รายการ</small>` : ""}</button>`;
  }).join("");
  const selectedDayEvents = calendarEventsForDay(selectedCalendarDay);
  const eventList = selectedDayEvents.length
    ? selectedDayEvents.map(item => `<button type="button" class="${item.id === selected?.id ? "active" : ""}" data-calendar-event="${item.id}"><strong>${getText(item.title)}</strong><small>${formatDate(item.date)} · ${item.time}</small></button>`).join("")
    : `<div class="empty-state compact"><strong>${currentLang === "th" ? "วันนี้ไม่มีรายการ" : "No events this day"}</strong><span>${currentLang === "th" ? "เลือกวันที่มีจุดสีเพื่อดูรายการ" : "Choose a highlighted day to see events."}</span></div>`;
  const detailHtml = selected ? `
    <div class="calendar-detail-card">
      <strong>${getText(selected.title)}</strong>
      <small>${formatDate(selected.date)} · ${selected.time} · ${getText(selected.owner)}</small>
      <p>${getText(selected.detail)}</p>
      <span>${getText(selected.location)}</span>
    </div>
  ` : `<div class="calendar-detail-card empty-detail"><strong>${currentLang === "th" ? "ยังไม่ได้เลือกรายการ" : "No event selected"}</strong><p>${currentLang === "th" ? "เลือกวันที่มีรายการ แล้วคลิกรายการเพื่อดูรายละเอียด" : "Choose a day with events, then click an event to see details."}</p></div>`;
  $("#calendarView").innerHTML = `
    <div class="panel">
      <div class="panel-header">
        <div><h3>ปฏิทินนิติบุคคล</h3><p>${googleCalendarConnected ? "เชื่อมต่อ Google Calendar mock สำเร็จ พร้อมแสดงรายการในตาราง Calendar" : "กดเชื่อมต่อเพื่อทดสอบ Google Calendar mock และเลือกวันเพื่อดูรายละเอียด"}</p></div>
        <div class="inline-actions">
          <button class="secondary-btn" id="connectGoogleCalendarBtn" type="button">${googleCalendarConnected ? "เชื่อมต่อแล้ว" : "เชื่อมต่อ Google Calendar"}</button>
          <button class="secondary-btn" id="shareCalendarBtn" type="button">แชร์ปฏิทิน</button>
        </div>
      </div>
      <div class="calendar-detail-top">
        <h3>รายละเอียดรายการ</h3>
        ${detailHtml}
      </div>
      <div class="calendar-layout">
        <div class="calendar-box">
          <div class="calendar-month">
            <button class="icon-btn" type="button" data-calendar-prev aria-label="เดือนก่อนหน้า">‹</button>
            <div class="calendar-month-title">
              <button type="button" data-calendar-pick-month>${calendarMonthName()}</button>
              <button type="button" data-calendar-pick-year>${calendarYearLabel()}</button>
            </div>
            <button class="icon-btn" type="button" data-calendar-next aria-label="เดือนถัดไป">›</button>
            <button class="calendar-today-btn" type="button" data-calendar-today>วันนี้</button>
          </div>
          ${calendarPickerHtml()}
          <div class="calendar-grid calendar-grid-buttons">
            <b>จ</b><b>อ</b><b>พ</b><b>พฤ</b><b>ศ</b><b>ส</b><b>อา</b>${cells}
          </div>
        </div>
        <div class="calendar-events">
          <h3>รายการวันที่ ${selectedCalendarDay} ${calendarMonthName()} ${calendarYearLabel()}</h3>
          <div class="calendar-event-list">
            ${eventList}
          </div>
        </div>
      </div>
      <div class="calendar-summary-grid">
        <section class="calendar-summary-card">
          <h3>กิจกรรมทั้งหมดที่เกิดขึ้นในวันนี้</h3>
          ${todayCalendarEvents().map(item => `<button type="button" data-calendar-event="${item.id}"><strong>${getText(item.title)}</strong><small>${item.time} · ${getText(item.owner)}</small></button>`).join("") || `<p class="muted-line">ยังไม่มีกิจกรรมวันนี้</p>`}
        </section>
        <section class="calendar-summary-card">
          <h3>กิจกรรมที่กำลังจะมาถึง 5 กิจกรรม</h3>
          ${upcomingCalendarEvents().map(item => `<button type="button" data-calendar-event="${item.id}"><strong>${getText(item.title)}</strong><small>${formatDate(item.date)} · ${item.time}</small></button>`).join("")}
        </section>
      </div>
    </div>`;
}
