  $("#residentBuildingFilter").innerHTML = `<option value="all">${currentLang === "th" ? "ทุกตึก" : "All buildings"}</option>` + buildings.map(building => `<option value="${esc(building)}" ${residentBuildingFilter === building ? "selected" : ""}>${esc(building)}</option>`).join("");
  const rooms = residentRooms.filter(matchesResidentFilters);
