document.addEventListener("dragstart", e => {
  const card = e.target.closest("[data-org-drag-user]");
  if (!card || !canManageOrganization()) return;
  e.dataTransfer.setData("text/plain", card.dataset.orgDragUser);
  e.dataTransfer.effectAllowed = "copy";
});
document.addEventListener("dragover", e => {
  const slot = e.target.closest("[data-org-slot]");
  if (!slot || !canManageOrganization()) return;
  e.preventDefault();
  slot.classList.add("drag-over");
});
document.addEventListener("dragleave", e => {
  const slot = e.target.closest("[data-org-slot]");
  if (slot) slot.classList.remove("drag-over");
});
document.addEventListener("drop", e => {
  const slot = e.target.closest("[data-org-slot]");
  if (!slot || !canManageOrganization()) return;
  e.preventDefault();
  slot.classList.remove("drag-over");
  const userId = e.dataTransfer.getData("text/plain");
  const user = getUser(userId);
  if (!user) return;
  const expectedDept = slot.dataset.acceptDept;
  if (inferDepartment(user) !== expectedDept) {
    return showToast(`ตำแหน่งนี้รับเฉพาะ ${departmentLabel(expectedDept)}`);
  }
  Object.keys(organizationDraftAssignments).forEach(slotId => {
    if (organizationDraftAssignments[slotId] === userId) delete organizationDraftAssignments[slotId];
  });
  organizationDraftAssignments[slot.dataset.orgSlot] = userId;
  organizationDirty = true;
  renderOrganization();
  showToast("จัดวางโปรไฟล์แล้ว กดบันทึกเพื่อแสดงในหน้าภาพรวม");
  return;
  showToast("บันทึกตำแหน่งใน Organization Chart แล้ว");
});
document.addEventListener("submit", async e => {
  const backhouseForm = e.target.closest("#backhouseUploadForm");
  if (backhouseForm) {
    e.preventDefault();
    if (!canManageOrganization()) return;
    const titleInput = backhouseForm.querySelector("[name='title']");
    const summaryInput = backhouseForm.querySelector("[name='summary']");
    const fileInput = backhouseForm.querySelector("[name='announcementFile']");
    const file = fileInput?.files?.[0];
    if (!file) return showToast(currentLang === "th" ? "กรุณาแนบเอกสารหรือรูปภาพ" : "Please attach a document or image");
    if (file.size > 12 * 1024 * 1024) return showToast(currentLang === "th" ? "ไฟล์ต้องมีขนาดไม่เกิน 12MB" : "File must be 12MB or less");
    const isPdf = file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf");
    const announcementId = `ann-${Date.now()}`;
    const src = await fileToDataUrl(file, "announcement", announcementId);
    announcements.unshift({
      id: announcementId,
      title: { th: titleInput.value.trim(), en: titleInput.value.trim() },
      type: isPdf ? "pdf" : "image",
      date: new Date().toISOString().slice(0, 10),
      audience: { th: "แสดงในหน้าภาพรวม", en: "Dashboard announcement" },
      summary: { th: summaryInput.value.trim(), en: summaryInput.value.trim() },
      pages: [src]
    });
    backhouseDirty = true;
    $("#backhouseUploadModal")?.classList.add("hidden");
    backhouseForm.reset();
    renderBackhouse();
    renderAnnouncements();
    showToast(currentLang === "th" ? "เพิ่มประกาศแล้ว กดบันทึกเพื่อยืนยัน" : "Announcement added. Save to confirm.");
    return;
  }
  const assignForm = e.target.closest("[data-assign-job]");
  if (assignForm) {
    e.preventDefault();
    const job = normalizeJob(jobs.find(j => j.id === assignForm.dataset.assignJob));
    const data = Object.fromEntries(new FormData(assignForm));
    let extra = {};
    if (job.startTime) {
      const conflicts = checkScheduleConflict(data.assignee, job.jobDate, job.startTime, job.endTime, job.id);
      if (conflicts.length) {
        const list = conflicts.map(item => `${item.startTime}-${effectiveEndTime(item.startTime, item.endTime)} ${item.id} ${getText(item.title)}`).join("\n");
        if (!confirm(`ผู้ได้รับมอบหมายคนนี้มีงานอยู่ในช่วงเวลาดังกล่าว:\n\n${list}\n\nยืนยันที่จะมอบหมายงานซ้อนหรือไม่?`)) return;
        extra = { hasScheduleConflict: true, conflictConfirmedAt: new Date().toISOString(), conflictConfirmedBy: currentUser.id };
      }
    }
    const assigned = await assignJob(job.id, data.assignee, { category: data.category, mainCategory: data.mainCategory, dueDate: data.dueDate, slaNote: data.slaNote, ...extra });
    if (supabaseEnabled() && !assigned) return; // fail closed: error toast already shown
    $("#jobModal").classList.add("hidden"); renderAll(); showToast(t("toast.assigned"));
  }
  const updateForm = e.target.closest("[data-update-job]");
  if (updateForm) {
    e.preventDefault();
    const job = normalizeJob(jobs.find(j => j.id === updateForm.dataset.updateJob));
    const data = Object.fromEntries(new FormData(updateForm));
    const files = getPhotoChoiceFiles(updateForm, "statusAttachments");
    if (files.length > 3) return showToast("แนบรูปได้สูงสุด 3 รูป");
    if (files.some(file => file.size > 5 * 1024 * 1024)) return showToast("รูปภาพต้องมีขนาดไม่เกิน 5MB ต่อไฟล์");
    const attachments = await Promise.all(files.map(file => fileToDataUrl(file, "job", job.id)));
    const result = await updateJobStatus(job.id, {
      status: data.status,
      inspectionDate: data.inspectionDate,
      updateDate: data.updateDate,
      cause: data.cause?.trim(),
      solution: data.solution?.trim(),
      note: data.note?.trim(),
      closePin: data.closePin?.trim(),
      completedWorkDate: data.completedWorkDate,
      nextUpdateDate: data.nextUpdateDate,
      noPinAvailable: !!data.noPinAvailable,
      noPinReason: data.noPinReason?.trim(),
      attachments
    });
    if (result.errors?.length) return showToast(result.errors[0]);
    $("#jobModal").classList.add("hidden"); renderAll(); showToast(t("toast.statusUpdated"));
  }
});
function getPhotoChoiceFiles(form, baseName) {
  const elements = form.elements || {};
  return [
    ...(elements[`${baseName}Camera`]?.files || []),
    ...(elements[`${baseName}Gallery`]?.files || []),
    ...(elements[baseName]?.files || [])
  ];
}
function getSinglePhotoChoiceFile(form, baseName) {
  return getPhotoChoiceFiles(form, baseName)[0] || null;
}
function readFileAsDataUrl(file) {
  return new Promise(resolve => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.readAsDataURL(file);
  });
}
function loadImage(src) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = reject;
    image.src = src;
  });
}
function imageStampText() {
  const userName = currentUser ? getUserName(currentUser) : "System";
  const stampTime = new Date().toLocaleString(currentLang === "th" ? "th-TH" : "en-US");
  return `${userName} · ${stampTime}`;
}
function fileFromDataUrl(dataUrl, originalFile) {
  const blob = dataUrlToBlob(dataUrl);
  return new File([blob], originalFile?.name || "upload", {
    type: blob.type || originalFile?.type || "application/octet-stream"
  });
}
async function uploadStoredMedia(file, dataUrl, kind = "job", ownerId = "draft") {
  if (!supabaseEnabled()) return dataUrl;
  try {
    const uploadFile = String(dataUrl).startsWith("data:") ? fileFromDataUrl(dataUrl, file) : file;
    const uploaders = {
      announcement: supabaseProvider.uploadAnnouncementFile,
      profile: supabaseProvider.uploadProfileImage,
      job: supabaseProvider.uploadJobAttachment
    };
    const upload = uploaders[kind] || uploaders.job;
    const stored = await upload(uploadFile, ownerId || "draft");
    const previewUrl = stored?.bucket && stored?.path ? await supabaseProvider.signedUrl(stored.bucket, stored.path, 3600) : "";
    return { ...stored, previewUrl, src: previewUrl, storageProvider: "supabase" };
  } catch (error) {
    console.warn("Supabase upload failed, using local preview", error);
    return dataUrl;
  }
}
async function fileToDataUrl(file, kind = "job", ownerId = "draft") {
  const dataUrl = await readFileAsDataUrl(file);
  if (!file?.type?.startsWith("image/")) return uploadStoredMedia(file, dataUrl, kind, ownerId);
  try {
    const image = await loadImage(dataUrl);
    const canvas = document.createElement("canvas");
    const maxSide = 1600;
    const scale = Math.min(1, maxSide / Math.max(image.naturalWidth || image.width, image.naturalHeight || image.height));
    canvas.width = Math.max(1, Math.round((image.naturalWidth || image.width) * scale));
    canvas.height = Math.max(1, Math.round((image.naturalHeight || image.height) * scale));
    const ctx = canvas.getContext("2d");
    ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
    const stamp = imageStampText();
    const fontSize = Math.max(14, Math.round(canvas.width * 0.024));
    const padding = Math.max(10, Math.round(fontSize * 0.7));
    ctx.font = `700 ${fontSize}px "Anuphan", "IBM Plex Sans Thai", Arial, sans-serif`;
    const textWidth = ctx.measureText(stamp).width;
    const boxWidth = Math.min(canvas.width, textWidth + padding * 2);
    const boxHeight = Math.round(fontSize + padding * 1.5);
    ctx.fillStyle = "rgba(7, 28, 22, 0.68)";
    ctx.fillRect(0, canvas.height - boxHeight, boxWidth, boxHeight);
    ctx.fillStyle = "#ffffff";
    ctx.fillText(stamp, padding, canvas.height - padding);
    return uploadStoredMedia(file, canvas.toDataURL("image/jpeg", 0.88), kind, ownerId);
  } catch (error) {
    console.warn("Image stamp failed, using original file", error);
    return uploadStoredMedia(file, dataUrl, kind, ownerId);
  }
}
$("#userForm").addEventListener("submit", async e => {
  e.preventDefault();
  if (!canManageTeam()) return;
  const form = e.currentTarget;
  const data = Object.fromEntries(new FormData(form));
  const profileFile = getSinglePhotoChoiceFile(form, "profileImage");
  const id = data.id || `u${String(Date.now()).slice(-6)}`;
  const department = data.department || "juristic";
  const role = department === "committee" || department === "juristic" || department === "technician" || department === "housekeeping" || department === "security_staff" || department === "gardener" || department === "contractor" ? "staff" : "resident";
  const newUser = {
    id,
    firstName: data.firstName.trim(),
    lastName: data.lastName.trim(),
    name: fullName(data.firstName.trim(), data.lastName.trim()),
    enName: fullName(data.firstName.trim(), data.lastName.trim()),
    nickName: data.nickName.trim(),
    position: data.position.trim(),
    department,
    room: data.room.trim().toUpperCase(),
    role,
    roleKey: departmentToRoleKey(department),
    password: genTempPassword(),
    mustChangePassword: true,
    assignL1: !!data.assignL1,
    assignL2: !!data.assignL2,
    profileImage: profileFile ? await fileToDataUrl(profileFile, "profile", id) : ""
  };
  users.push(newUser);
  customUsers.push(newUser);
  saveCustomUsers();
  teamOverrides[newUser.id] = { ...newUser };
  saveTeamOverrides();
  addLog("USER_ADDED", `${getUserName(newUser)} added by ${getUserName(currentUser)}`);
  $("#userModal").classList.add("hidden");
  renderAll();
  showToast(currentLang === "th"
    ? `เพิ่มผู้ใช้งานแล้ว · รหัสชั่วคราว: ${newUser.password} (ให้ผู้ใช้เปลี่ยนเมื่อเข้าครั้งแรก)`
    : `User added · temporary password: ${newUser.password} (user must change on first login)`);
});
$("#passwordForm").addEventListener("submit", e => {
  e.preventDefault();
  const data = Object.fromEntries(new FormData(e.currentTarget));
  const user = getUser(data.userId);
  if (!user) return;
  const canChange = currentUser.role === "admin" || currentUser.id === user.id;
  if (!canChange) return;
  user.password = data.password.trim();
  persistUserFields(user);
  addLog("PASSWORD_CHANGED", `${getUserName(user)} password changed by ${getUserName(currentUser)}`);
  $("#passwordModal").classList.add("hidden");
  renderTeam();
  showToast(currentLang === "th" ? "เปลี่ยนรหัสผ่านแล้ว" : "Password changed");
});
$("#profileForm").addEventListener("submit", e => {
  e.preventDefault();
  saveOwnProfile(e.currentTarget);
});
$("#createJobBtn").addEventListener("click", () => {
  if (!hasActionPermission("createJob")) return showToast(currentLang === "th" ? "บัญชีนี้ไม่มีสิทธิ์สร้างงาน" : "This account cannot create jobs");
  $("#createJobForm").elements.jobDate.value = new Date().toISOString().slice(0, 10);
  if ($("#createDueDate")) $("#createDueDate").value = addDaysIso(7);
  $("#createModal").classList.remove("hidden");
});
$("#createJobForm").addEventListener("submit", async e => {
  e.preventDefault();
  if (!hasActionPermission("createJob")) return showToast(currentLang === "th" ? "บัญชีนี้ไม่มีสิทธิ์สร้างงาน" : "This account cannot create jobs");
  const form = e.currentTarget;
  const data = Object.fromEntries(new FormData(form));
  if (data.endTime && !data.startTime) return showToast("ถ้ากรอกเวลาสิ้นสุด ต้องกรอกเวลาเริ่มงานด้วย");
  const files = getPhotoChoiceFiles(form, "initialAttachments");
  // Stage 4 (F4): creation-time attachments are not yet supported in Supabase
  // mode (create_job has no evidence parameter). Block BEFORE any upload so no
  // orphaned Storage object can exist; photos are added via a status update.
  if (supabaseEnabled() && files.length) {
    return showToast("โหมด Supabase ยังไม่รองรับการแนบรูปตอนสร้างงาน กรุณาสร้างงานก่อน แล้วเพิ่มรูปผ่านการอัปเดตสถานะ / Attachments at job creation are not yet supported; create the job first, then add photos via a status update");
  }
  if (files.length > 3) return showToast("แนบรูปภาพได้สูงสุด 3 รูป");
  if (files.some(file => file.size > 5 * 1024 * 1024)) return showToast("รูปภาพต้องมีขนาดไม่เกิน 5MB ต่อไฟล์");
  let conflictExtra = {};
  if (data.assignee && data.startTime) {
    const conflicts = checkScheduleConflict(data.assignee, data.jobDate, data.startTime, data.endTime);
    if (conflicts.length) {
      const assignee = getUser(data.assignee);
      const list = conflicts.map(job => `${job.startTime}-${effectiveEndTime(job.startTime, job.endTime)} ${job.id} ${getText(job.title)}`).join("\n");
      const ok = confirm(`ผู้ได้รับมอบหมายคนนี้มีงานอยู่ในช่วงเวลาดังกล่าว:\n\n${list}\n\nยืนยันที่จะมอบหมายงานซ้อนหรือไม่?\n\nหากยืนยัน กรุณาโทรแจ้งผู้ได้รับมอบหมาย${assignee?.phone ? `ที่เบอร์ ${assignee.phone}` : ""} ก่อนดำเนินการ`);
      if (!ok) return;
      conflictExtra = { hasScheduleConflict: true, conflictConfirmedAt: new Date().toISOString(), conflictConfirmedBy: currentUser.id };
    }
  }
  const draftJobId = `draft-${Date.now()}`;
  const attachments = await Promise.all(files.map(file => fileToDataUrl(file, "job", draftJobId)));
  const created = await createJob({ ...data, initialAttachments: attachments, ...conflictExtra });
  if (supabaseEnabled() && !created) return; // fail closed: error toast already shown
  form.reset();
  $("#createModal").classList.add("hidden");
  renderAll();
  showToast(t("toast.created"));
});
