document.addEventListener("input", e => {
  if (e.target?.id === "permissionSearchInput") {
    permissionSearch = e.target.value;
    renderPermissions();
  }
  if (e.target?.id === "logPersonSearchFilter") {
    logPersonSearchFilter = e.target.value;
    renderLogs();
  }
  if (e.target?.id === "staffJobFilterSearch") {
    const q = normalizeSearchText(e.target.value);
    $$("#staffJobFilterMenu label").forEach(label => {
      label.classList.toggle("hidden", q && !normalizeSearchText(label.textContent).includes(q));
    });
  }
  const excelSearch = e.target?.closest("[data-excel-search]");
  if (excelSearch) {
    const id = excelSearch.dataset.excelSearch;
    const q = normalizeSearchText(excelSearch.value);
    $$(`[data-excel-option-row="${id}"]`).forEach(label => {
      label.classList.toggle("hidden", q && !normalizeSearchText(label.textContent).includes(q));
    });
  }
});
$("#residentCsvInput").addEventListener("change", e => {
  const file = e.target.files?.[0];
  if (file && (canManageResidents() || hasActionPermission("importExport"))) importResidentsCsv(file);
  e.target.value = "";
});
$("#employeeCsvInput").addEventListener("change", e => {
  const file = e.target.files?.[0];
  if (file && canManageTeam()) importEmployeesCsv(file);
  e.target.value = "";
});
document.addEventListener("change", async e => {
  if (e.target?.id === "permissionDepartmentFilter") {
    permissionDepartmentFilter = e.target.value;
    renderPermissions();
    return;
  }
  if (e.target?.id === "logStartDateFilter") {
    logStartDateFilter = e.target.value;
    renderLogs();
    return;
  }
  if (e.target?.id === "logEndDateFilter") {
    logEndDateFilter = e.target.value;
    renderLogs();
    return;
  }
  const excelOption = e.target?.closest("[data-excel-option]");
  if (excelOption) {
    const id = excelOption.dataset.excelOption;
    const values = $$(`[data-excel-option="${id}"]:checked`).map(input => input.value);
    if (id === "logDepartment") {
      logDepartmentFilters = values;
      logPersonFilters = [];
    } else if (id === "logPerson") {
      logPersonFilters = values;
    }
    renderLogs();
    $(`[data-excel-menu="${id}"]`)?.classList.remove("hidden");
    return;
  }
  const financeImport = e.target.closest("#financeImportInput");
  if (financeImport) {
    const file = financeImport.files?.[0];
    if (file && canImportFinance()) {
      addLog("FINANCE_IMPORTED", `${file.name} imported by ${getUserName(currentUser)}`);
      showToast(currentLang === "th" ? `Import งบการเงิน mock: ${file.name}` : `Finance mock imported: ${file.name}`);
    }
    financeImport.value = "";
  }
  const backhouseUpload = e.target.closest("#backhouseUploadInput");
  if (backhouseUpload) {
    const file = backhouseUpload.files?.[0];
    if (file && canManageAnnouncements()) {
      const isPdf = file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf");
      const announcementId = `ann-${Date.now()}`;
      const src = await fileToDataUrl(file, "announcement", announcementId);
      announcements.unshift({
        id: announcementId,
        title: { th: file.name.replace(/\.[^.]+$/, ""), en: file.name.replace(/\.[^.]+$/, "") },
        type: isPdf ? "pdf" : "image",
        date: new Date().toISOString().slice(0, 10),
        audience: { th: "แสดงในหน้าภาพรวม", en: "Dashboard announcement" },
        summary: { th: isPdf ? "ไฟล์ PDF ที่อัปโหลดจากประกาศ" : "รูปภาพที่อัปโหลดจากประกาศ", en: isPdf ? "PDF uploaded from Announcements" : "Image uploaded from Announcements" },
        pages: [src]
      });
      backhouseDirty = true;
      renderBackhouse();
      renderAnnouncements();
      showToast(currentLang === "th" ? "เพิ่มประกาศแล้ว กดบันทึกเพื่อยืนยัน" : "Announcement added. Save to confirm.");
    }
    backhouseUpload.value = "";
  }
  const statusSelect = e.target.closest("[data-status-select]");
  if (statusSelect) syncStatusFields(statusSelect);
  const noPin = e.target.closest("[name='noPinAvailable']");
  if (noPin) syncStatusFields(noPin.closest("form")?.querySelector("[data-status-select]"));
  const currentPerson = e.target.closest("[data-current-person]");
  if (currentPerson) currentPerson.closest(".resident-primary-card")?.classList.toggle("selected", currentPerson.checked);
});
$("#logStartDateFilter")?.addEventListener("change", e => {
  logStartDateFilter = e.target.value;
  renderLogs();
});
$("#logEndDateFilter")?.addEventListener("change", e => {
  logEndDateFilter = e.target.value;
  renderLogs();
});

applyTeamOverrides();
jobs = jobs.map(normalizeJob).filter(Boolean);
if (!supabaseEnabled()) saveJobs();
translateStaticDom();
applyDeviceMode();
window.addEventListener("resize", () => { clearTimeout(applyDeviceMode.timer); applyDeviceMode.timer = setTimeout(applyDeviceMode, 120); });
const sessionUser = getUser(sessionStorage.getItem("juristicUser"));
(async () => {
  if (supabaseEnabled()) {
    try {
      const backendUser = await supabaseProvider.loadCurrentUserContext();
      if (backendUser) {
        await showApp(upsertRuntimeUser(backendUser));
        return;
      }
    } catch (error) {
      console.warn("Supabase session restore failed", error);
    }
  }
  if (sessionUser) await showApp(sessionUser);
})();
